#!/usr/bin/env python3
# -*- coding: utf-8 -*-
"""
Reproducibility copy
--------------------
Copied on 2026-08-12 from ``../../keyence20x_arc_me_with_plots.py``.
Source SHA256: f17d51cd1a94056348460caf872683f6461696689f4fee4de5229008128cf7e1

Keyence 20x POMC / NPY / c-FOS full pipeline, v17 ARC/ME anatomy with final compact ARC/ME statistics plots
===========================================================================

Single-script replacement for the previous 4-step workflow:

  1) 01_migrate_and_rename_20x.py
  2) batch_cellpose_segment.py
  3) quantify_fos_npy_pomc.py
  4) plot_cfos_stats.py

What this script does
---------------------
A. Uses your existing 20x_sanitized folder when it is present.
B. If 20x_sanitized is missing, it can create a sanitized copy from the raw 20x folder.
C. Keeps all existing/manual *_seg.npy files. It never overwrites them unless you pass
   --overwrite-seg.
D. Segments only missing masks when --segment-missing is active.
E. Quantifies DAPI-associated c-FOS/POMC/NPY using de-overlapped assignments.
F. Keeps strict DAPI/c-FOS overlap by default, with an optional blur-aware mode for 30 µm sections.
G. Reconstructs left+right sections, preserves the validated v17 projected-wall ARC/ME anatomy, then produces per-animal summaries, ARC/ME QC PDFs, and compact two-panel ME/ARC publication plots. No left/right or VMN/OTHER analysis is generated by default.

Expected biology / channel map
------------------------------
CH1 = DAPI
CH2 = NPY  (optional; some samples do not have it)
CH3 = POMC
CH4 = c-FOS

Default paths are resolved from this project checkout:
  raw root       : <project-root>/20x
  sanitized root : <project-root>/20x_sanitized

Quick run
---------
  python 02_keyence20x_arc_me_pipeline.py --setup-only
  python 02_keyence20x_arc_me_pipeline.py --full-run --no-segment-missing

Dry run first
-------------
  python 02_keyence20x_arc_me_pipeline.py --dry-run

Use a custom sample sheet
-------------------------
  python 02_keyence20x_arc_me_pipeline.py --full-run --no-segment-missing --samplesheet samplesheet.csv

Only quantify existing manual segmentations, without running Cellpose
--------------------------------------------------------------------
  python 02_keyence20x_arc_me_pipeline.py --full-run --no-segment-missing


LZW TIFF compatibility
----------------------
Keyence TIFFs are often LZW-compressed. The dedicated conda environment now
installs imagecodecs explicitly, because tifffile requires it to decode LZW.
The reader also has a Pillow fallback, but imagecodecs is preferred.

ARC / ME anatomical rule
------------------------
The script robustly fits the left and right third-ventricle walls and projects
those two wall tangents ventrally. When the lumen is oval, the projection starts
from the lateral tangent points of the oval rather than following its rounded
ventral cap. ME is restricted to the closed ventricular floor below the detected
lumen-floor curve and between the projected walls. Nuclei along the ventricular
sidewalls are reassigned to ARC. Every other nucleus is ARC. No fixed horizontal
ARC/ME line is drawn, and c-FOS/NPY/POMC signal is not used to place the boundary.

Important defaults
------------------
  --cfos-association-mode strict --cfos-dapi-overlap 0.40
      c-FOS is strict by default. Use --cfos-association-mode blur-aware only if you want to tolerate Z-focus blur.

  --pomc-expand-um 7.5
      POMC is treated as DAPI-associated cell-body signal, not necessarily exactly inside
      the DAPI nuclear pixels.

  --npy-expand-um 7.5
      Same association logic for NPY when CH2 is present.

  --pct-pomc-npy-overlap 0.20
      Removes POMC ROIs whose area overlaps NPY by >=20%, to reduce false POMC/NPY
      double positives in adult hypothalamic sections.
"""

