def _first_existing(*candidates: Path) -> Path:
    """First candidate that exists, else the first one.

    Every Figure 4 input ships inside this tree, so the defaults must name a
    path that an unpacked archive actually contains. A private working copy
    under analyses/Fig4 still wins when it is present.
    """
    for candidate in candidates:
        if candidate.exists():
            return candidate
    return candidates[0]


def _latest_prepared_review_input() -> Optional[Path]:
    """Newest shipped prepared review stage, if the tree carries one."""
    if not FIG4_HIL_REVIEW_ROOT.is_dir():
        return None
    stages = sorted(
        path for path in FIG4_HIL_REVIEW_ROOT.glob("prepared_review_input_*")
        if (path / "reconstructed_sections").is_dir()
    )
    return stages[-1] if stages else None


def _latest_accepted_hil_root() -> Optional[Path]:
    """Newest shipped human-final accepted review, if the tree carries one."""
    if not FIG4_HIL_REVIEW_ROOT.is_dir():
        return None
    roots = sorted(
        path for path in FIG4_HIL_REVIEW_ROOT.glob("human_final_*")
        if path.is_dir() and any(path.glob("*/*/*.json"))
    )
    return roots[-1] if roots else None


